 public function assertOrderParties(array $header):void
 {
  $entry=($header['tipo']??'saida')==='entrada';
  $personId=(int)($entry?($header['fornecedor_id']??0):($header['cliente_id']??0));
  $personTable=$entry?'fornecedores':'clientes';
